1	import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
2	import prisma from "../lib/prisma.js";
3	import jwt from "jsonwebtoken";
4	
5	const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
6	
7	// Authorization 헤더에서 토큰 추출
8	function extractToken(request: FastifyRequest): string | null {
9	  const auth = request.headers.authorization;
10	  if (!auth) return null;
11	  const match = auth.match(/^Token\s+(.+)$/i);
12	  return match ? match[1] : null;
13	}
14	
15	// 토큰 디코딩 (예외 처리 포함)
16	function verifyToken(token: string): { id: string; username: string; email: string } | null {
17	  try {
18	    return jwt.verify(token, JWT_SECRET) as any;
19	  } catch {
20	    return null;
21	  }
22	}
23	
24	// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거
25	function slugify(title: string): string {
26	  return title
27	    .toLowerCase()
28	    .trim()
29	    .replace(/[^\w\s-]/g, "")
30	    .replace(/[\s_]+/g, "-")
31	    .replace(/^-+|-+$/g, "");
32	}
33	
34	// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
35	function normalizeTags(tagList: (string | null | undefined)[]): string[] {
36	  if (!tagList) return [];
37	  const tags = tagList
38	    .map((t) => {
39	      if (t === null || t === undefined || t === "") return null;
40	      return t.trim().toLowerCase();
41	    })
42	    .filter((t): t is string => t !== null && t !== "");
43	  return [...new Set(tags)];
44	}
45	
46	export async function articlesRoutes(app: FastifyInstance): Promise<void> {
47	  // POST /api/articles - 아티클 생성
48	  app.post("/api/articles", async (request, reply) => {
49	    const token = extractToken(request);
50	    if (!token) {
51	      return reply.code(401).send({ errors: { token: ["is missing"] } });
52	    }
53	
54	    const { article } = (request.body as any) as { article?: any };
55	    const { title, description, body, tagList } = article || {};
56	
57	    // 필수 필드 검증
58	    if (!title || title.trim() === "") {
59	      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
60	    }
61	    if (!description || description.trim() === "") {
62	      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
63	    }
64	    if (!body || body.trim() === "") {
65	      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
66	    }
67	
68	    const decoded = verifyToken(token);
69	    if (!decoded) {
70	      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
71	    }
72	    const normalizedTags = normalizeTags(tagList);
73	
74	    // 태그 조회/생성 (트랜잭션)
75	    let tagRecords: { id: string; name: string }[] = [];
76	    if (normalizedTags.length > 0) {
77	      const existingTags = await prisma.tag.findMany({
78	        where: { name: { in: normalizedTags } },
79	        select: { id: true, name: true },
80	      });
81	      const existingNames = new Set((existingTags as Array<{ name: string }>).map((t) => t.name));
82	      const newTags = normalizedTags.filter((n) => !existingNames.has(n));
83	
84	      if (newTags.length > 0) {
85	        await prisma.tag.createMany({
86	          data: newTags.map((name) => ({ name })),
87	        });
88	      }
89	      tagRecords = await prisma.tag.findMany({
90	        where: { name: { in: normalizedTags } },
91	        select: { id: true, name: true },
92	      });
93	    }
94	
95	    const slug = slugify(title);
96	    const created = await prisma.article.create({
97	      data: {
98	        title: title.trim(),
99	        description: description.trim(),
100	        body: body.trim(),
101	        slug,
102	        authorId: decoded.id,
103	        tagList: {
104	          connect: tagRecords.map((t) => ({ id: t.id })),
105	        },
106	      },
107	      include: {
108	        author: {
109	          select: { id: true, username: true, bio: true, image: true },
110	        },
111	        tags: { select: { name: true } },
112	      },
113	    });
114	
115	    return reply.code(201).send({
116	      article: {
117	        title: created.title,
118	        slug: created.slug,
119	        description: created.description,
120	        body: created.body,
121	        tagList: (created.tags as Array<{ name: string }>).map((t) => t.name),
122	        createdAt: created.createdAt,
123	        updatedAt: created.updatedAt,
124	        favorited: false,
125	        favoritesCount: 0,
126	        author: {
127	          username: created.author.username,
128	          bio: created.author.bio ?? null,
129	          image: created.author.image ?? null,
130	        },
131	      },
132	    });
133	  });
134	
135	  // GET /api/articles - 아티클 목록 조회 (필터: author, tag, favorited)
136	  app.get("/api/articles", async (request: any, reply) => {
137	    const token = extractToken(request);
138	    const authorFilter = request.query?.author as string | undefined;
139	    const tagFilter = request.query?.tag as string | undefined;
140	    const favoritedFilter = request.query?.favorited as string | undefined;
141	    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);
142	    const offset = parseInt(request.query?.offset as string ?? "0", 10);
143	
144	    // favorited 필터 — 먼저 존재하여 articleIds 확보
145	    let favArticleIds: string[] = [];
146	    if (favoritedFilter) {
147	      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });
148	      if (!favUser) {
149	        return reply.send({ articles: [], articlesCount: 0 });
150	      }
151	      favArticleIds = await prisma.$queryRaw<string[]>`
152	        SELECT article_id FROM "Favorite" WHERE user_id = ${favUser.id}
153	      `;
154	    }
155	
156	    // author 필터
157	    let authorId: string | undefined;
158	    if (authorFilter) {
159	      const author = await prisma.user.findUnique({ where: { username: authorFilter } });
160	      if (!author) {
161	        return reply.send({ articles: [], articlesCount: 0 });
162	      }
163	      authorId = author.id;
164	    }
165	
166	    // tag 필터
167	    let tagId: string | undefined;
168	    if (tagFilter) {
169	      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });
170	      if (!tag) {
171	        return reply.send({ articles: [], articlesCount: 0 });
172	      }
173	      tagId = tag.id;
174	    }
175	
176	    // where 조건 구성
177	    const where: any = {};
178	    if (authorId) where.authorId = authorId;
179	    if (favArticleIds.length > 0) {
180	      where.id = { in: favArticleIds };
181	    }
182	    if (tagId) {
183	      where.tags = { some: { id: tagId } };
184	    }
185	
186	    // 전체 카운트
187	    const total = await prisma.article.count({ where });
188	
189	    const articles = await prisma.article.findMany({
190	      where,
191	      include: {
192	        author: {
193	          select: { id: true, username: true, bio: true, image: true },
194	        },
195	        tags: { select: { name: true } },
196	      },
197	      orderBy: { createdAt: "desc" },
198	      take: limit,
199	      skip: offset,
200	    });
201	
202	    // favorited 상태 확인 (토큰이 있는 경우)
203	    let currentUserId: string | null = null;
204	    if (token) {
205	      try {
206	        currentUserId = verifyToken(token).id;
207	      } catch {
208	        // invalid token, treat as no auth
209	      }
210	    }
211	
212	    // favorited 상태 batch 체크
213	    const articleIds = articles.map((a: any) => a.id);
214	    let favoritedMap: Record<string, boolean> = {};
215	    let favCountMap: Record<string, number> = {};
216	
217	    if (articleIds.length > 0) {
218	      const favResults = await prisma.$queryRaw<{ article_id: string; user_id: string }[]>`
219	        SELECT article_id, user_id FROM "Favorite" WHERE article_id IN (${articleIds})
220	      `;
221	      for (const row of favResults) {
222	        if (!favCountMap[row.article_id]) favCountMap[row.article_id] = 0;
223	        favCountMap[row.article_id]++;
224	        if (row.user_id === currentUserId) {
225	          favoritedMap[row.article_id] = true;
226	        }
227	      }
228	    }
229	
230	    const result = articles.map((a: any) => ({
231	      title: a.title,
232	      slug: a.slug,
233	      description: a.description,
234	      tagList: (a.tags as Array<{ name: string }>).map((t) => t.name),
235	      createdAt: a.createdAt,
236	      updatedAt: a.updatedAt,
237	      favorited: favoritedMap[a.id] ?? false,
238	      favoritesCount: favCountMap[a.id] ?? 0,
239	      author: {
240	        username: a.author.username,
241	        bio: a.author.bio ?? null,
242	        image: a.author.image ?? null,
243	      },
244	    }));
245	
246	    return reply.send({
247	      articles: result,
248	      articlesCount: total,
249	    });
250	  });
251	
252	  // GET /api/articles/:slug - 단일 아티클 조회
253	  app.get("/api/articles/:slug", async (request: any, reply) => {
254	    const slug = request.params.slug as string;
255	    const token = extractToken(request);
256	
257	    const article = await prisma.article.findUnique({
258	      where: { slug },
259	      include: {
260	        author: {
261	          select: { id: true, username: true, bio: true, image: true },
262	        },
263	        tags: { select: { name: true } },
264	      },
265	    });
266	
267	    if (!article) {
268	      return reply.code(404).send({ errors: { article: ["not found"] } });
269	    }
270	
271	    // favorited 상태 확인
272	    let favorited = false;
273	    let favoritesCount = 0;
274	    let currentUserId: string | null = null;
275	    if (token) {
276	      try {
277	        currentUserId = verifyToken(token).id;
278	      } catch {
279	        // ignore
280	      }
281	    }
282	
283	    const favResult = await prisma.$queryRaw<{ article_id: string; user_id: string }[]>`
284	      SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${article.id}
285	    `;
286	    for (const row of favResult) {
287	      favoritesCount++;
288	      if (row.user_id === currentUserId) favorited = true;
289	    }
290	
291	    return reply.send({
292	      article: {
293	        title: article.title,
294	        slug: article.slug,
295	        description: article.description,
296	        body: article.body,
297	        tagList: (article.tags as Array<{ name: string }>).map((t) => t.name),
298	        createdAt: article.createdAt,
299	        updatedAt: article.updatedAt,
300	        favorited,
301	        favoritesCount,
302	        author: {
303	          username: article.author.username,
304	          bio: article.author.bio ?? null,
305	          image: article.author.image ?? null,
306	        },
307	      },
308	    });
309	  });
310	
311	  // PUT /api/articles/:slug - 아티클 수정
312	  app.put("/api/articles/:slug", async (request: any, reply) => {
313	    const slug = request.params.slug as string;
314	    const token = extractToken(request);
315	    if (!token) {
316	      return reply.code(401).send({ errors: { token: ["is missing"] } });
317	    }
318	
319	    const article = await prisma.article.findUnique({
320	      where: { slug },
321	      include: { author: true, tags: true },
322	    });
323	    if (!article) {
324	      return reply.code(404).send({ errors: { article: ["not found"] } });
325	    }
326	
327	    const decoded = verifyToken(token);
328	    if (!decoded) {
329	      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
330	    }
331	    if (decoded.id !== article.authorId) {
332	      return reply.code(403).send({ errors: { article: ["not found"] } });
333	    }
334	
335	    const { article: updateData } = (request.body as any) as { article?: any };
336	    const updates: any = {};
337	    const tagList = updateData?.tagList;
338	
339	    if (updateData.title !== undefined && updateData.title.trim() !== "") {
340	      updates.title = updateData.title.trim();
341	    }
342	    if (updateData.description !== undefined) updates.description = updateData.description.trim();
